header_type_specs.canonical_declaration:
typedef struct http_tcp_callbacks {
    http_tcp_on_accept_fn on_accept;
    http_tcp_on_event_fn on_event;
    http_tcp_on_close_fn on_close;
} http_tcp_callbacks_t;

typedef enum http_method {
    HTTP_GET = 0,
    HTTP_HEAD = 1,
    HTTP_POST = 2,
    HTTP_UNKNOWN = 3,
} http_method_t;

typedef struct http_header {
    char name[HTTP_MAX_HEADER_NAME];
    char value[HTTP_MAX_HEADER_VALUE];
} http_header_t;

typedef struct http_request {
    http_method_t method;
    char uri[HTTP_MAX_URI];
    http_header_t headers[HTTP_MAX_HEADERS];
    size_t header_count;
    char* body;
    size_t body_len;
} http_request_t;

typedef struct http_session {
    int fd;
    http_connection_t* conn;
} http_session_t;
